<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {api,post} from '../api';
import {state,action,inform} from '../state';
import {date} from '../format';
import AlgorithmPicker from '../components/AlgorithmPicker.vue';
import AlgorithmResults from '../components/AlgorithmResults.vue';
import type {LabAlgorithm,LabTask,HistoryStatus,LabWorkspace} from '../algorithmLab';
import {labWorkspace as ws,labResults,activeLabJob,workspaceNames,draftConfig,sameConfig,startLabWorkspace,startCalculation,cancelCalculation,openRun,clone,carryStockStudy,runWorkspace} from '../labWorkspace';
import type {ResearchStock} from '../labWorkspace';
const emit=defineEmits<{open:[string];rules:[]}>();
const tabs=[{id:'screen',name:'选股工作台',hint:'多股票筛选'},{id:'stock',name:'个股分析',hint:'核对单只股票'},{id:'monitor',name:'持续监测',hint:'条件变化提醒'},{id:'history',name:'运行记录',hint:'重看计算结果'}] as const;
const key=computed<LabWorkspace>(()=>ws.tab==='history'?'screen':ws.tab),draft=computed(()=>ws.drafts[key.value]);
const selected=computed({get:()=>draft.value.selectionsByMode[draft.value.mode]??[],set:value=>{draft.value.selectionsByMode[draft.value.mode]=value;}});
const run=computed(()=>ws.tab==='history'?undefined:labResults[key.value]),dirty=computed(()=>!!run.value&&!sameConfig(run.value,key.value));
const busy=computed(()=>activeLabJob.value?.workspace===key.value||ws.submitting===key.value),filterMode=computed(()=>key.value==='stock'?'custom':draft.value.scope);
const catalog=ref<LabAlgorithm[]>([]),coverage=ref<HistoryStatus>(),tasks=ref<LabTask[]>([]),events=ref<any[]>([]),modelStatus=ref<any>();
const err=ref(''),q=ref(''),searchResults=ref<ResearchStock[]>([]),searching=ref(false),viewing=ref(''),now=ref(Date.now());
const resultSection=ref<HTMLElement>(),configSection=ref<HTMLElement>();
let poll:ReturnType<typeof setInterval>,clock:ReturnType<typeof setInterval>,searchTimer:ReturnType<typeof setTimeout>,searchVersion=0,disposed=false,loadBusy=false;
const algorithmNames=(selections:{id:string}[])=>selections.map(s=>catalog.value.find(a=>a.id===s.id)?.name??s.id).join(' / ');
const modeName=(mode:string)=>({daily:'完成日线',intraday:'当日分时',news:'关联公告'}[mode]??mode);
const scopeName=(scope:string,total?:number)=>({all:'全部沪深证券',watch:'我的自选',custom:'指定 '+(total??draft.value.chosen.length)+' 只股票',saved:'已打开 / 已保存'}[scope]??scope);
function summary(c:{mode:string;scope:string;selections:{id:string}[];combination:string;security_ids?:string[]}){return scopeName(c.scope,c.security_ids?.length)+' · '+modeName(c.mode)+' · '+(c.combination==='all'?'同时满足':'任一满足')+' · '+(algorithmNames(c.selections)||'尚未选择算法');}
const configSummary=computed(()=>summary(draftConfig(key.value)));
const jobPercent=computed(()=>activeLabJob.value?.total?Math.floor(activeLabJob.value.completed/activeLabJob.value.total*100):0);
const elapsed=computed(()=>activeLabJob.value?Math.max(0,Math.floor((now.value-Date.parse(activeLabJob.value.started_at))/1000)):0);
const lastJob=computed(()=>ws.jobs.find(j=>j.workspace===key.value));
const history=computed(()=>{
  const successful=new Set(ws.runs.map(r=>r.id));
  return [...ws.runs.map(r=>({...r,workspace:runWorkspace(r),recordType:'run'})),...ws.jobs.filter(j=>!successful.has(j.run_id)).map(j=>({...j.config,id:j.id,started_at:j.started_at,status:j.status,total:j.total,matched:j.matched,skipped:j.skipped,workspace:j.workspace,recordType:'job',error:j.error}))].sort((a,b)=>b.started_at.localeCompare(a.started_at));
});
function switchTab(tab:typeof ws.tab){ws.tab=tab;q.value='';searchResults.value=[];++searchVersion;}
async function load(){if(loadBusy)return;loadBusy=true;try{const [h,t]=await Promise.all([api<HistoryStatus>('/history/status'),api<{tasks:LabTask[];events:any[]}>('/lab/tasks')]);if(!disposed){coverage.value=h.data;tasks.value=t.data.tasks;events.value=t.data.events;}}catch(e){if(!disposed)err.value=String(e);}finally{loadBusy=false;}}
function search(){clearTimeout(searchTimer);const version=++searchVersion;searchResults.value=[];if(!q.value.trim()){searching.value=false;return;}searching.value=true;searchTimer=setTimeout(async()=>{try{const r=await api<ResearchStock[]>('/securities?q='+encodeURIComponent(q.value));if(version===searchVersion&&!disposed)searchResults.value=r.data.slice(0,8);}catch(e){err.value=String(e);}finally{if(version===searchVersion)searching.value=false;}},200);}
function choose(s:ResearchStock){draft.value.chosen=key.value==='stock'?[s]:[...draft.value.chosen.filter(x=>x.id!==s.id),s];q.value='';searchResults.value=[];++searchVersion;}
function preset(id:string){const pairs:Record<string,string[]>={trend:['ma-trend','atr-risk'],rebound:['rsi','atr-risk'],breakout:['volume-breakout','atr-risk']};selected.value=(pairs[id]??[]).map(id=>({id,parameters:clone(catalog.value.find(a=>a.id===id)!.parameters)}));}
async function calculate(){await startCalculation(key.value);await nextTick();if(activeLabJob.value)document.querySelector('.lab-job-panel')?.scrollIntoView({block:'center',behavior:'smooth'});}
async function viewHistory(id:string){viewing.value=id;err.value='';try{await openRun(id);await nextTick();resultSection.value?.scrollIntoView({block:'start',behavior:'smooth'});resultSection.value?.focus({preventScroll:true});}catch(e){err.value=String(e);}finally{viewing.value='';}}
function jumpResults(){if(activeLabJob.value)ws.tab=activeLabJob.value.workspace;void nextTick(()=>configSection.value?.scrollIntoView({block:'start',behavior:'smooth'}));}
async function saveTask(){const config=draftConfig('monitor'),d=ws.drafts.monitor;const result=await action(()=>post('/lab/tasks',{...config,name:d.taskName,interval_seconds:d.interval,enabled:true,auto_review:d.autoReview,use_jev:d.useJev,id:d.editingId}),'监测已启用；首次建立基线，之后条件变化才提醒。');if(result){d.editingId=undefined;d.paramsOpen=false;await load();}}
async function toggleTask(t:LabTask){if(await action(()=>post('/lab/tasks',{...t,enabled:!t.enabled})))await load();}
async function removeTask(t:LabTask){if(await action(()=>api('/lab/tasks/'+t.id,{method:'DELETE'})))await load();}
function prepareMonitor(id:string){const source=run.value;if(!source)return;const sec=source.rows.find(r=>r.security.id===id)?.security;if(!sec)return;const d=ws.drafts.monitor;d.mode=source.mode;d.scope='custom';d.chosen=[{...sec}];d.selectionsByMode[source.mode]=clone(source.selections);d.combination=source.combination;d.paramsOpen=true;d.editingId=undefined;d.taskName=sec.name+' · 条件监测';switchTab('monitor');inform('已带入这次计算条件，确认频率后启用监测。');void nextTick(()=>configSection.value?.scrollIntoView({block:'start',behavior:'smooth'}));}
function editTask(t:LabTask){const d=ws.drafts.monitor;d.editingId=t.id;d.mode=t.mode;d.scope=t.scope;d.chosen=(t.security_ids??[]).map(id=>state.securities.find(s=>s.id===id)??{id,name:id,code:id.split('.').at(-1)??id});d.selectionsByMode[t.mode]=clone(t.selections);d.combination=t.combination;d.taskName=t.name;d.interval=t.interval_seconds;d.autoReview=t.auto_review;d.useJev=!!t.use_jev;d.paramsOpen=true;switchTab('monitor');void nextTick(()=>configSection.value?.scrollIntoView({block:'start',behavior:'smooth'}));}
async function fillHistory(){if(await action(()=>post('/history/start'),'已启动历史补数'))await load();}
const statusName=(s:string)=>({QUEUED:'等待计算',RUNNING:'计算中',CANCELLING:'正在取消',SUCCEEDED:'已完成',FAILED:'失败',CANCELLED:'已取消',INTERRUPTED:'上次中断'}[s]??s);
function openStock(id:string){if(run.value)carryStockStudy(run.value,id);emit('open',id);}
onMounted(async()=>{startLabWorkspace();try{const [a,m]=await Promise.all([api<LabAlgorithm[]>('/lab/catalog'),api('/lab/model-status')]);if(!disposed){catalog.value=a.data;modelStatus.value=m.data;}}catch(e){err.value=String(e);}await load();if(!disposed){poll=setInterval(load,10000);clock=setInterval(()=>now.value=Date.now(),1000);}});
onUnmounted(()=>{disposed=true;clearInterval(poll);clearInterval(clock);clearTimeout(searchTimer);++searchVersion;});
</script>
<template>
  <section class="lab-heading"><div><span class="eyebrow">发现 · 算法研究</span><h1>算法选股与监测</h1><p>先筛选候选，在个股上核对依据，再为关注股票开启条件提醒。</p></div><span class="badge">研究版 · 无自动交易</span></section>
  <div class="lab-tabs" role="tablist" aria-label="发现工作区"><button v-for="t in tabs" :key="t.id" role="tab" :aria-selected="ws.tab===t.id" :class="{active:ws.tab===t.id}" @click="switchTab(t.id)"><strong>{{t.name}}</strong><small>{{t.hint}}</small></button></div>
  <div class="lab-data-strip" v-if="coverage"><span><strong>{{coverage.coverage.history_count.toLocaleString()}}</strong> / {{coverage.coverage.catalog_count.toLocaleString()}} 只已有日线</span><span>最近历史 {{coverage.coverage.last_date??'尚未下载'}}</span><details v-if="coverage.coverage.quality_warning_count"><summary>{{coverage.coverage.quality_warning_count}} 只存在来源质量诊断</summary><p>无效OHLC行被剔除，未补造价格。逐只日期见发行覆盖清单，算法还会检查最低数据量。</p></details><span v-if="coverage.status==='RUNNING'">补数中 {{coverage.completed}} / {{coverage.total}}</span><button class="text-button" :disabled="coverage.status==='RUNNING'" @click="fillHistory">{{coverage.status==='RUNNING'?'历史补数中…':'补齐历史'}}</button></div>
  <div v-if="activeLabJob" class="lab-job-panel" role="status"><div class="lab-section-title"><strong>{{workspaceNames[activeLabJob.workspace]}} · {{statusName(activeLabJob.status)}}</strong><span>已用 {{elapsed}} 秒</span><button v-if="ws.tab!==activeLabJob.workspace" class="text-button" @click="jumpResults">返回任务</button><button class="button small" :disabled="activeLabJob.status==='CANCELLING'" @click="action(()=>cancelCalculation(activeLabJob!.id))">{{activeLabJob.status==='CANCELLING'?'正在取消…':'取消计算'}}</button></div><progress :value="activeLabJob.completed" :max="activeLabJob.total||1" aria-label="算法计算进度"/><div class="lab-progress-text"><strong>{{activeLabJob.completed.toLocaleString()}} / {{activeLabJob.total.toLocaleString()}} 只 · {{jobPercent}}%</strong><span>已满足 {{activeLabJob.matched}} 只 · 数据不足 {{activeLabJob.skipped}} 只</span><span>{{activeLabJob.current}}</span></div><p class="tiny muted">{{summary(activeLabJob.config)}}。可以切换页面，计算会继续；完整结果自动保存在所属工作区。</p></div>
  <p v-if="ws.connectionError" class="error-box" role="alert">任务状态暂时无法同步：{{ws.connectionError}}。恢复连接后自动重取，不会重复提交计算。</p><p v-if="err" class="error-box" role="alert">{{err}}</p>
  <template v-if="ws.tab!=='history'">
    <section ref="configSection" class="lab-config panel"><div class="lab-section-title"><div><span class="lab-step">01 / 条件</span><h2>{{key==='screen'?'设置选股条件':key==='stock'?'选择股票与分析方法':draft.editingId?'调整监测任务':'建立监测任务'}}</h2></div><button class="text-button" @click="draft.paramsOpen=!draft.paramsOpen">{{draft.paramsOpen?'收拢配置':'展开配置'}}</button></div>
      <div class="lab-config-summary"><strong>{{configSummary}}</strong><span v-if="filterMode==='custom'&&draft.chosen.length">{{draft.chosen.map(s=>s.name+' '+s.code).join('、')}}</span><span v-if="dirty" class="lab-changed">条件已修改，下面保留上次结果；重新运行后更新。</span></div>
      <fieldset v-show="draft.paramsOpen" :disabled="busy" class="lab-fields"><div class="lab-config-row"><label>数据周期<select v-model="draft.mode"><option value="daily">完成日线</option><option value="intraday">当日分时成交价</option><option value="news">关联公告事件</option></select></label><label v-if="key!=='stock'">股票范围<select v-model="draft.scope"><option value="watch">我的自选</option><option value="custom">指定股票池</option><option value="all" v-if="key==='screen'">全部沪深证券</option><option value="saved">已打开 / 已保存</option></select></label><label>组合方式<select v-model="draft.combination"><option value="all">所有算法同时满足</option><option value="any">任一算法满足</option></select></label></div>
        <div v-if="filterMode==='custom'" class="lab-stock-picker"><label>{{key==='stock'?'选择分析股票':'添加研究股票'}}<input v-model="q" @input="search" placeholder="输入代码、名称或拼音" aria-label="搜索研究股票" @keydown.enter.prevent="searchResults[0]&&choose(searchResults[0])"></label><span v-if="searching" class="tiny muted">搜索中…</span><div class="lab-search-results" v-if="searchResults.length"><button v-for="s in searchResults" :key="s.id" @click="choose(s)">{{s.name}} <span>{{s.code}}</span></button></div><div class="lab-chosen"><button v-for="s in draft.chosen" :key="s.id" :aria-label="'移除 '+s.name" @click="draft.chosen=draft.chosen.filter(x=>x.id!==s.id)">{{s.name}} {{s.code}} ×</button></div><p v-if="!draft.chosen.length" class="tiny muted">{{key==='stock'?'搜索并选择一只股票，再计算它满足哪些条件。':'请选择研究股票；每个监测任务最多20只。'}}</p></div>
        <div class="lab-presets" v-if="draft.mode==='daily'"><span>从常用组合开始</span><button class="button small" @click="preset('trend')">趋势＋风险过滤</button><button class="button small" @click="preset('rebound')">低位回升观察</button><button class="button small" @click="preset('breakout')">放量突破观察</button></div>
        <div class="lab-algorithm-title"><strong>选择算法 · 已选 {{selected.length}} 项</strong><span class="tiny muted">{{draft.combination==='all'?'勾选越多，筛选越严格；可从两项开始。':'任一条件符合即入选，请核对其他算法的风险。'}}</span></div><AlgorithmPicker :catalog="catalog" v-model="selected" :mode="draft.mode"/>
        <div class="lab-task-options" v-if="key==='monitor'"><label>任务名称<input v-model="draft.taskName" maxlength="60"></label><label>检查间隔<select v-model="draft.interval"><option :value="30">30 秒</option><option :value="60">60 秒</option><option :value="300">5 分钟</option></select></label><label class="lab-inline-check"><input type="checkbox" v-model="draft.useJev" :disabled="!modelStatus?.jev?.configured">Jev 决策分流（{{modelStatus?.jev?.configured?'已配置':'待配置密钥'}}）</label><label class="lab-inline-check"><input type="checkbox" v-model="draft.autoReview" :disabled="!modelStatus?.agent_configured">触发后 Agent 复核（{{modelStatus?.agent_configured?'可能计费，每小时≤4组':'待配置模型'}}）</label></div>
      </fieldset><p v-if="ws.errors[key]" class="error-box" role="alert">{{ws.errors[key]}}</p>
      <div class="lab-run-bar"><div class="tiny muted">{{key==='monitor'?(draft.mode==='daily'?'日线随补数更新；首次检查只建立基线。':'新数据到达后检查；首次检查只建立基线。'):'完整结果自动保留在下方和运行记录。'}}<br v-if="activeLabJob&&activeLabJob.workspace!==key"><span v-if="activeLabJob&&activeLabJob.workspace!==key">{{workspaceNames[activeLabJob.workspace]}}正在计算，结束后可运行本工作区。</span></div><button class="button" :class="{primary:key!=='monitor'}" :disabled="!!activeLabJob||!!ws.submitting||!selected.length||(filterMode==='custom'&&!draft.chosen.length)" @click="calculate">{{busy?'正在计算…':key==='screen'?'开始选股':key==='stock'?'分析这只股票':'试算监测条件'}}</button><button v-if="key==='monitor'" class="button primary" :disabled="busy||!selected.length||(filterMode==='custom'&&!draft.chosen.length)" @click="saveTask">{{draft.editingId?'保存调整并重建基线':'启用监测'}}</button><button v-if="draft.editingId" class="text-button" @click="draft.editingId=undefined">取消调整</button></div>
    </section>
    <section ref="resultSection" tabindex="-1" class="lab-result-area" :aria-busy="busy"><div class="lab-section-title"><div><span class="lab-step">02 / {{key==='monitor'?'试算':'结果'}}</span><h2>{{key==='screen'?'选股结果':key==='stock'?'个股分析结果':'监测条件试算结果'}}</h2></div><span v-if="busy" class="badge blue">新计算进行中</span><span v-else-if="run" class="badge">{{dirty?'上次结果 · 条件已修改':'已完成'}}</span></div>
      <div v-if="lastJob&&['FAILED','CANCELLED','INTERRUPTED'].includes(lastJob.status)" class="lab-job-outcome" role="status"><strong>{{statusName(lastJob.status)}}</strong> · {{lastJob.error}}<button class="text-button" :disabled="!!activeLabJob" @click="calculate">按当前条件重新运行</button></div>
      <template v-if="run"><p class="tiny muted">本次结果：{{scopeName(run.scope,run.total)}} · {{modeName(run.mode)}} · {{algorithmNames(run.selections)}} · {{run.combination==='all'?'同时满足':'任一满足'}}</p><p v-if="busy" class="tiny muted">下面保留上一份完整结果，新计算完成后自动更新。</p><AlgorithmResults :run="run" :workspace-state="draft" @open="openStock" @monitor="prepareMonitor" @adjust="draft.paramsOpen=true;configSection?.scrollIntoView({block:'start',behavior:'smooth'})"/></template>
      <div v-else-if="busy" class="lab-empty lab-computing"><h3>正在逐只计算，结果会自动出现在这里。</h3><p>可以先去其他页面查看行情，返回后继续查看进度。</p></div><div v-else-if="ws.loading" class="lab-empty">正在恢复上次任务和结果…</div><div v-else class="lab-empty"><h3>{{key==='screen'?'设置条件后，点击“开始选股”。':key==='stock'?'先选一只股票，再点击“分析这只股票”。':'先试算条件，确认后启用持续监测。'}}</h3><p>{{key==='screen'?'优先展示满足条件的候选，每只股票可以展开依据、打开K线或带入监测。':key==='stock'?'逐项说明满足和未满足的条件，点击股票名称可进入K线页面。':'试算检查当前条件，启用监测后自动跟踪变化并通知。'}}</p></div>
    </section>
    <section v-if="key==='monitor'" class="lab-monitor-list"><div class="lab-section-title"><h2>已保存的监测任务</h2><span class="tiny muted">{{tasks.filter(t=>t.enabled).length}} 个启用 · 客户端运行时执行</span></div><div v-if="!tasks.length" class="lab-empty">目前没有监测任务。选择股票、算法和频率后启用。</div><article class="lab-task" v-for="t in tasks" :key="t.id"><div><strong>{{t.name}}</strong><span class="badge" :class="t.enabled?'blue':''">{{t.enabled?'监测中':'已暂停'}}</span><p class="tiny muted">{{modeName(t.mode)}} · {{algorithmNames(t.selections)}} · 每 {{t.interval_seconds}} 秒</p><p class="tiny">最近检查 {{t.last_checked_at?date(t.last_checked_at):'等待首次基线'}}<span class="error-line" v-if="t.error"> · {{t.error}}</span></p></div><button class="button small" @click="editTask(t)">调整</button><button class="button small" @click="toggleTask(t)">{{t.enabled?'暂停':'恢复'}}</button><button class="text-button" @click="removeTask(t)">删除</button></article><h2 class="lab-event-heading">触发流水</h2><div v-if="!events.length" class="lab-empty">尚无新触发。首次检查、编辑或恢复任务时建立基线，之后的新事件才提醒。</div><article v-for="e in events" :key="e.id" class="lab-task"><div><strong>{{e.row.security.name}} · {{e.task_name}}</strong><p>{{e.row.action}}</p><span class="tiny muted">{{date(e.created_at)}} · 数据 {{e.row.data_as_of}}</span><p v-if="e.decision">Jev：{{e.decision.summary}}</p><p v-if="e.model_note">{{e.model_note}}</p><p v-if="e.review">Agent：{{e.review.summary}}</p></div><button class="text-button" @click="emit('open',e.row.security.id)">查看个股</button></article></section>
  </template>
  <section v-else class="lab-history"><div class="lab-section-title"><h2>运行记录</h2><span class="tiny muted">完整结果保留最近15次 · 点击恢复条件并定位结果</span></div><div v-if="!history.length" class="lab-empty">还没有计算记录。开始一次计算后，这里会保留状态与结果。</div><article v-for="r in history" :key="r.id" class="lab-task"><div><strong>{{date(r.started_at)}}</strong><span class="badge">{{statusName(r.status)}}</span><p>{{workspaceNames[r.workspace??'screen']}} · {{algorithmNames(r.selections)}}</p><span class="tiny muted">{{scopeName(r.scope,r.total)}} · {{modeName(r.mode)}} · {{r.combination==='all'?'同时满足':'任一满足'}} · {{r.recordType==='run'?'已计算':'计划计算'}} {{r.total}} 只 · 满足 {{r.matched}} 只 · 数据不足 {{r.skipped}} 只</span><p class="error-line tiny" v-if="'error' in r&&r.error">{{r.error}}</p></div><button v-if="r.recordType==='run'" class="button small" :disabled="!!viewing" @click="viewHistory(r.id)">{{viewing===r.id?'正在恢复…':'查看结果'}}</button><button v-else-if="['RUNNING','QUEUED','CANCELLING'].includes(r.status)" class="button small" @click="jumpResults">查看进度</button></article></section>
  <p class="lab-footer-note">规则命中用于研究，尚未完成盈利概率校准。Jev / Agent 仅在显式开启并配置后调用。日线为未复权原价，分时是来源成交价序列，客户端关闭后监测停止。</p>
</template>
